import crosswalkFile from './crosswalk171.generated.json';
import type { GeneratedCrosswalkFile } from './types';
import type { ControlMapping } from '../../../types/framework';
import { CMMC_LEVEL_2_CONTROLS } from '../cmmcLevel2Controls';
import { CMMC_LEVEL_1_CONTROLS } from '../../cmmcLevel1Controls';
import { NIST_800_53_CONTROLS } from '../nist80053Controls';

/**
 * Crosswalk between NIST SP 800-171 Rev. 2 requirements (the CMMC Level 1 / Level 2 practices) and NIST SP 800-53 Rev. 5
 * controls, from SP 800-171 Rev. 2 Appendix D (generated by scripts/generateNist80053.ts).
 *
 * Pure and shared by the browser and the server. It must not import frameworkRegistry or controlMappings (controlMappings
 * imports this module to build its rows).
 */
const crosswalk = crosswalkFile as unknown as GeneratedCrosswalkFile;

export const CROSSWALK_PROVENANCE = 'NIST SP 800-171 Rev. 2 Appendix D';

export interface Crosswalk53Counterpart {
  /** SP 800-53 Rev. 5 control id, e.g. "AC-6(1)". */
  control: string;
  title: string;
  kind: 'BASE' | 'ENHANCEMENT';
  /** The base control of an enhancement. */
  parent?: string;
  /** Set when Appendix D named a Rev. 4 control that Rev. 5 withdrew and NIST's withdrawn-control link carried forward. */
  rev4?: string;
}

export interface Crosswalk171Reference {
  requirement: string;
  cmmcIds: string[];
  rev4?: string;
}

export interface Crosswalk171ViaParent extends Crosswalk171Reference {
  /** The base control the requirement is mapped to. */
  parent: string;
}

const REQUIREMENT_RE = /(?:^|-)(3\.\d{1,2}\.\d{1,2})$/;

/** "AC.L2-3.1.5" or "3.1.5" -> "3.1.5"; null for anything else (for example an SP 800-53 id). */
export function requirementNumberOf(controlId: string): string | null {
  const m = REQUIREMENT_RE.exec(controlId.trim());
  return m ? m[1] : null;
}

const byRequirement = new Map<string, string[]>();
for (const c of CMMC_LEVEL_2_CONTROLS) {
  const req = requirementNumberOf(c.id);
  if (!req) continue;
  const list = byRequirement.get(req) ?? [];
  list.push(c.id);
  byRequirement.set(req, list);
}
const l1Ids = new Set(CMMC_LEVEL_1_CONTROLS.map((c) => c.id));

const catalogById = new Map(NIST_800_53_CONTROLS.map((c) => [c.id.toUpperCase(), c]));

function compareRequirements(a: string, b: string): number {
  const pa = a.split('.').map(Number);
  const pb = b.split('.').map(Number);
  for (let i = 0; i < 3; i++) if (pa[i] !== pb[i]) return (pa[i] ?? 0) - (pb[i] ?? 0);
  return 0;
}

/** The CMMC control ids (as the Level 2 catalog defines them) for an SP 800-171 requirement number such as "3.1.5". */
export function cmmcIdsForRequirement(requirement: string): string[] {
  return [...(byRequirement.get(requirement) ?? [])];
}

/** Every SP 800-171 requirement number that has a crosswalk entry, in order. */
export function crosswalkRequirements(): string[] {
  return Object.keys(crosswalk.requirements).sort(compareRequirements);
}

/** The requirements Appendix D gives no SP 800-53 Rev. 5 control for (withdrawn controls without a successor). */
export function withdrawnWithoutSuccessor(): Record<string, string[]> {
  return { ...crosswalk.withdrawnWithoutSuccessor };
}

function describe53(control: string, rev4?: string): Crosswalk53Counterpart {
  const def = catalogById.get(control.toUpperCase());
  return {
    control,
    title: def?.title ?? control,
    kind: def?.controlKind === 'ENHANCEMENT' ? 'ENHANCEMENT' : 'BASE',
    ...(def?.parentControlId ? { parent: def.parentControlId } : {}),
    ...(rev4 ? { rev4 } : {}),
  };
}

const forward = new Map<string, Crosswalk53Counterpart[]>();
for (const [req, entries] of Object.entries(crosswalk.requirements)) {
  forward.set(req, entries.map((e) => describe53(e.control, e.rev4)));
}

/** The SP 800-53 Rev. 5 counterparts of a CMMC / SP 800-171 control (empty for any other control). */
export function crosswalkFor171(controlId: string): Crosswalk53Counterpart[] {
  const req = requirementNumberOf(controlId);
  return req ? [...(forward.get(req) ?? [])] : [];
}

const inverse = new Map<string, Array<{ requirement: string; rev4?: string }>>();
for (const req of crosswalkRequirements()) {
  for (const e of crosswalk.requirements[req]) {
    const key = e.control.toUpperCase();
    const list = inverse.get(key) ?? [];
    list.push({ requirement: req, ...(e.rev4 ? { rev4: e.rev4 } : {}) });
    inverse.set(key, list);
  }
}

/**
 * The SP 800-171 requirements (and their CMMC ids) that map to an SP 800-53 control. `direct` are mapped to the control itself;
 * `viaParent`, for an enhancement, are mapped to its base control (so they relate to the enhancement only through that parent).
 */
export function crosswalkFor53(controlId: string): { direct: Crosswalk171Reference[]; viaParent: Crosswalk171ViaParent[] } {
  const key = controlId.trim().toUpperCase();
  const toRef = (e: { requirement: string; rev4?: string }): Crosswalk171Reference => ({
    requirement: e.requirement,
    cmmcIds: cmmcIdsForRequirement(e.requirement),
    ...(e.rev4 ? { rev4: e.rev4 } : {}),
  });
  const direct = (inverse.get(key) ?? []).map(toRef);
  const def = catalogById.get(key);
  const parent = def?.controlKind === 'ENHANCEMENT' ? def.parentControlId : undefined;
  const directReqs = new Set(direct.map((d) => d.requirement));
  const viaParent: Crosswalk171ViaParent[] = parent
    ? (inverse.get(parent.toUpperCase()) ?? []).filter((e) => !directReqs.has(e.requirement)).map((e) => ({ ...toRef(e), parent }))
    : [];
  return { direct, viaParent };
}

/**
 * The crosswalk as control-mapping rows: CMMC Level 2 (and, for the practices that are also in the Level 1 catalog, CMMC
 * Level 1) -> SP 800-53 Rev. 5. SUBSET, because Appendix D relates a requirement to only the part of the 800-53 control that
 * it covers. Ids are deterministic. Callers drop any (source, target) pair a hand-curated mapping already covers.
 */
export function buildCrosswalkMappingRows(): ControlMapping[] {
  const rows: ControlMapping[] = [];
  for (const req of crosswalkRequirements()) {
    const ids = cmmcIdsForRequirement(req);
    for (const e of crosswalk.requirements[req]) {
      const title = describe53(e.control).title;
      const provenance = e.rev4
        ? `${CROSSWALK_PROVENANCE} (Rev. 4 ${e.rev4} carried to Rev. 5 ${e.control} via NIST's withdrawn-control link)`
        : CROSSWALK_PROVENANCE;
      for (const id of ids) {
        const base = { sourceControlId: id, targetFramework: 'NIST_800_53_REV5' as const, targetControlId: e.control, mappingType: 'SUBSET' as const };
        const notes = `${provenance}: ${req} relates to ${e.control} (${title}); only the part of the control that the requirement addresses applies`;
        rows.push({ id: `x171-${req}-${e.control}`, sourceFramework: 'CMMC_L2', notes, provenance, ...base });
        if (l1Ids.has(id)) rows.push({ id: `x171-l1-${req}-${e.control}`, sourceFramework: 'CMMC_L1', notes, provenance, ...base });
      }
    }
  }
  return rows;
}
